                                    <div role="main" id="mc-main-content">
                                        <h1 class="script">Perform Script</h1>
                                        <p class="ref-purpose-script"><span class="mc-variable ui-strings-scriptsteps.vExecScript variable">Performs a script specified from a list or calculated by name.</span>
                                        </p>
                                        <div class="ref-see-also-block">
                                            <h2 class="ref-see-also-head" data-mc-autonum="See also"><span class="autonumber"><span>See also</span></span>&#160;</h2>
                                            <ul class="ref-see-also-list">
                                                <li><a href="scripts.html" class="MCXref xref">Automating tasks with scripts</a>
                                                </li>
                                            </ul>
                                        </div>
                                        <h2 class="ref-options-head" data-mc-autonum="Options"><span class="autonumber"><span>Options</span></span>&#160;</h2>
                                        <ul>
                                            <li><strong>Specified: </strong>
                                                <ul>
                                                    <li><strong>From list </strong>allows you to select the script you want to perform.</li>
                                                    <li><strong>By name </strong>allows you to specify the script name by a calculation. The script name is not case sensitive.</li>
                                                </ul>
                                            </li>
                                            <li><strong>Parameter</strong> specifies a script parameter for the specified script.</li>
                                        </ul>
                                        <div class="compat-wrapper">
                                            <h2 class="ref-compat-head" data-mc-autonum="Compatibility"><span class="autonumber"><span>Compatibility</span></span>&#160;</h2>
                                            <table class="TableStyle-CompTable" style="mc-table-style: url(''resources/tablestyles/comptable.css'');" cellspacing="0">
                                                <thead>
                                                    <tr class="TableStyle-CompTable-Head-Header1">
                                                        <td class="TableStyle-CompTable-HeadE-Column1-Header1"><span class="mc-variable compatibility-table-values.Heading:Product variable">Product</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-HeadD-Column2-Header1"><span class="mc-variable compatibility-table-values.Heading:Supported variable">Supported</span>
                                                        </td>
                                                    </tr>
                                                </thead>
                                                <tbody>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:Pro variable">FileMaker Pro</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:Yes variable">Yes</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:Go variable">FileMaker Go</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:Yes variable">Yes</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:WebD variable">FileMaker WebDirect</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:Yes variable">Yes</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:Server variable">FileMaker Server</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:Yes variable">Yes</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:Cloud variable">FileMaker Cloud</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:Yes variable">Yes</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:DAPI variable">FileMaker Data API</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:Yes variable">Yes</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyB-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:CWP variable">Custom Web Publishing</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyA-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:Yes variable">Yes</span>
